/**
 * Bank Soal & Konfigurasi Paket Pretest CAT Polri (Seleksi SIP / Akpol / Bintara)
 * Diperbarui sesuai standar CAT Polri:
 * 1. Kecerdasan: Logika Spasial/Figural, Denah Wilayah, Aritmatika Dasar, dan Silogisme/Verbal (100 Soal, 90 Menit)
 * 2. Kepribadian: Studi Kasus Realistis Lingkungan Kedinasan Polri SJT (100 Soal, 60 Menit)
 * 3. Kecermatan: Format Monokrom CAT Putih (10 Kolom @ 50 Soal = 500 Soal, 1 Menit/Kolom)
 * 4. TKK: Tes Kemampuan Komputer (100 Soal, 90 Menit)
 * 5. TPK: Tes Pengetahuan Kepolisian (100 Soal, 60 Menit)
 */

export interface SimOption {
  key: string;
  text: string;
  weight?: number;
}

export interface SimBenchmarkItem {
  char: string;
  label: string;
}

export interface SimQuestion {
  id: number;
  module: string;
  subtest?: 'KECERDASAN' | 'KEPRIBADIAN' | 'KECERMATAN' | 'TKK' | 'TPK';
  stem: string;
  image?: string;
  options: SimOption[];
  correctKey: string;
  explanation: string;
  weight?: number;
  optionWeights?: Record<string, number>;
  dimension?: string;
  isKecermatan?: boolean;
  columnNumber?: number;
  benchmark?: SimBenchmarkItem[];
  questionChars?: string[];
}

export interface SimPacket {
  id: string;
  category: 'PSIKOTES' | 'TKK' | 'TPK' | 'ALL';
  subtest?: 'ALL' | 'KECERDASAN' | 'KEPRIBADIAN' | 'KECERMATAN';
  title: string;
  subtitle: string;
  description: string;
  badge: string;
  durationSeconds: number;
  isKecermatanOnly?: boolean;
  columnDurationSeconds?: number;
  questions: SimQuestion[];
}

